package com.campus.market.product;

import com.campus.market.auth.SessionService;
import com.campus.market.user.UserResponse;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.test.context.DynamicPropertyRegistry;
import org.springframework.test.context.DynamicPropertySource;
import org.springframework.test.context.bean.override.mockito.MockitoSpyBean;
import org.springframework.test.web.servlet.MockMvc;
import java.sql.*;
import java.util.*;
import java.util.concurrent.*;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@SpringBootTest(properties={"spring.datasource.username=root","spring.datasource.password=","spring.flyway.enabled=true","market.product-cache.enabled=false","market.login-protection.enabled=false","market.orders.mq.enabled=false","market.orders.timeout-sweep-enabled=false","springdoc.api-docs.enabled=false"})
@AutoConfigureMockMvc
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="LESSON85_DB_URL",matches="jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/campus_lesson85_verify\\?.*")
class ProductModerationIntegrationTest {
    static Connection control;static String schema,url;
    @DynamicPropertySource static void database(DynamicPropertyRegistry registry)throws Exception {
        String base=System.getenv("LESSON85_DB_URL");control=DriverManager.getConnection(base,"root","");
        try(var s=control.createStatement();var r=s.executeQuery("SELECT @@datadir")){assertTrue(r.next());assertTrue(r.getString(1).contains("campus-lesson24-"));}
        schema="campus_lesson90_case_"+UUID.randomUUID().toString().replace("-","").substring(0,12);
        try(var s=control.createStatement()){s.execute("CREATE DATABASE "+schema+" CHARACTER SET utf8mb4");}
        url=base.replace("/campus_lesson85_verify?","/"+schema+"?");registry.add("spring.datasource.url",()->url);
    }
    @AfterAll static void removeSchema()throws Exception {if(control!=null)try{if(schema!=null&&schema.matches("campus_lesson90_case_[0-9a-f]{12}"))try(var s=control.createStatement()){s.execute("DROP DATABASE "+schema);}}finally{control.close();}}
    @Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired SessionService sessions;
    @MockitoSpyBean ProductDetailCache cache;
    final JsonMapper json=JsonMapper.builder().build();String admin,seller,other,secondAdmin;
    @BeforeEach void fixtures(){
        for(String table:List.of("product_moderation","product_moderation_events","order_timeout_outbox","order_events","market_orders","product_favorites","products","user_role_audit","user_role_grants","login_sessions","users"))jdbc.update("DELETE FROM "+table);
        jdbc.update("INSERT INTO users(id,username,password_hash,nickname) VALUES(101,'review_admin','not-used','审核员'),(102,'review_seller','not-used','卖家'),(103,'review_other','not-used','其他账号'),(104,'review_admin2','not-used','审核员乙')");
        jdbc.update("INSERT INTO user_role_grants(user_id,role_code) VALUES(101,'ADMIN'),(104,'ADMIN')");
        jdbc.update("INSERT INTO products(id,title,description,price_in_cents,seller_id,status,category_code) VALUES(201,'审核教材','整改前描述',3500,102,'ON_SALE','BOOK'),(202,'下架台灯','',100,102,'OFF_SHELF','DAILY'),(203,'已售出物品','',100,102,'SOLD','OTHER'),(204,'历史商品','',100,NULL,'ON_SALE','UNCLASSIFIED')");
        admin=token(101,"review_admin","审核员");seller=token(102,"review_seller","卖家");other=token(103,"review_other","其他账号");secondAdmin=token(104,"review_admin2","审核员乙");clearInvocations(cache);
    }
    String token(long id,String name,String nick){return "Bearer "+sessions.issueToken(new UserResponse(id,name,nick)).accessToken();}
    Map<String,Object> payload(String action,long version,String reason,String request){return Map.of("action",action,"version",version,"reason",reason,"requestId",request);}
    String key(){return UUID.randomUUID().toString();}
    org.springframework.mock.web.MockHttpServletResponse action(long id,String actor,Map<String,?> body)throws Exception {return mvc.perform(post("/api/admin/products/"+id+"/moderation/actions").header("Authorization",actor).contentType("application/json").content(json.writeValueAsString(body))).andReturn().getResponse();}
    JsonNode success(org.springframework.mock.web.MockHttpServletResponse r)throws Exception {assertEquals(200,r.getStatus(),r.getContentAsString());assertEquals("no-store",r.getHeader("Cache-Control"));return json.readTree(r.getContentAsByteArray());}
    JsonNode block(long id,long version)throws Exception {return success(action(id,admin,payload("BLOCK",version,"平台发现违规内容",key())));}
    JsonNode get(String path,String actor)throws Exception {var request=getRequest(path,actor);var response=mvc.perform(request).andReturn().getResponse();assertEquals(200,response.getStatus(),response.getContentAsString());if(path.startsWith("/api/admin")||path.contains("/moderation")||path.contains("/feed"))assertEquals("no-store",response.getHeader("Cache-Control"));return json.readTree(response.getContentAsByteArray());}
    org.springframework.test.web.servlet.request.MockHttpServletRequestBuilder getRequest(String path,String actor){var request=org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get(path);return actor==null?request:request.header("Authorization",actor);}
    int getStatus(String path,String actor)throws Exception {return mvc.perform(getRequest(path,actor)).andReturn().getResponse().getStatus();}
    org.springframework.mock.web.MockHttpServletResponse appeal(long id,String actor,long version,String reason,String request)throws Exception {return mvc.perform(post("/api/products/"+id+"/moderation/appeals").header("Authorization",actor).contentType("application/json").content(json.writeValueAsString(Map.of("version",version,"reason",reason,"requestId",request)))).andReturn().getResponse();}
    int sellerStatus(long id,String status,long version)throws Exception {return mvc.perform(put("/api/products/"+id+"/status").header("Authorization",seller).contentType("application/json").content(json.writeValueAsString(Map.of("status",status,"version",version)))).andReturn().getResponse().getStatus();}
    long version(long id){return jdbc.queryForObject("SELECT version FROM products WHERE id=?",Long.class,id);}
    int events(){return jdbc.queryForObject("SELECT COUNT(*) FROM product_moderation_events",Integer.class);}
    String state(long id){return jdbc.queryForObject("SELECT state FROM product_moderation WHERE product_id=?",String.class,id);}
    int createOrder()throws Exception {return mvc.perform(post("/api/products/201/orders").header("Authorization",other).contentType("application/json").content(json.writeValueAsString(Map.of("productVersion",0,"requestId",key())))).andReturn().getResponse().getStatus();}
    List<Integer> parallel(Callable<Integer> a,Callable<Integer> b)throws Exception {var pool=Executors.newFixedThreadPool(2);try{var x=pool.submit(a);var y=pool.submit(b);return List.of(x.get(15,TimeUnit.SECONDS),y.get(15,TimeUnit.SECONDS));}finally{pool.shutdownNow();assertTrue(pool.awaitTermination(5,TimeUnit.SECONDS));}}

    @Test void anonymousAndOrdinaryCannotReadOrWriteModeration()throws Exception {for(String path:List.of("/api/admin/products","/api/admin/products/201/moderation")){assertEquals(401,getStatus(path,null));assertEquals(403,getStatus(path,seller));}assertEquals(403,action(201,seller,payload("BLOCK",0,"越权操作",key())).getStatus());assertEquals(0,events());}
    @Test void adminCanSearchAllStatusesAndLegacyProducts()throws Exception {var all=get("/api/admin/products?size=20",admin);assertEquals(4,all.path("total").asInt());assertEquals(4,all.path("records").size());assertTrue(all.path("records").get(0).path("product").path("seller").isNull());assertEquals(1,get("/api/admin/products?status=SOLD",admin).path("total").asInt());assertEquals(1,get("/api/admin/products?keyword=教材",admin).path("total").asInt());}
    @Test void listValidatesPageSizeStatusKeywordAndState()throws Exception {for(String query:List.of("page=0","size=21","status=BAD","moderationState=BAD","keyword="+"x".repeat(51)))assertEquals(400,getStatus("/api/admin/products?"+query,admin));}
    @Test void wildcardSearchIsLiteralAndPaginationStable()throws Exception {jdbc.update("UPDATE products SET title='百分%_!教材' WHERE id=201");assertEquals(1,success(mvc.perform(getRequest("/api/admin/products",admin).param("keyword","%_!")).andReturn().getResponse()).path("total").asInt());var a=get("/api/admin/products?size=2&page=1",admin);var b=get("/api/admin/products?size=2&page=2",admin);var ids=new HashSet<Long>();a.path("records").forEach(i->ids.add(i.path("product").path("id").asLong()));b.path("records").forEach(i->ids.add(i.path("product").path("id").asLong()));assertEquals(4,ids.size());}
    @Test void blockHidesProductAdvancesVersionAndWritesEvidence()throws Exception {var receipt=block(201,0);assertFalse(receipt.path("replayed").asBoolean());assertEquals("BLOCKED",state(201));assertEquals(1,version(201));assertEquals("OFF_SHELF",jdbc.queryForObject("SELECT status FROM products WHERE id=201",String.class));var event=receipt.path("detail").path("events").get(0);assertEquals("ADMIN",event.path("actorRole").asString());assertEquals("整改前描述",event.path("snapshot").path("description").asString());assertEquals(3500,event.path("snapshot").path("priceInCents").asLong());assertEquals(1,events());verify(cache).evictAfterCommit(201,0);}
    @Test void blockedProductCannotBeRelistedOrMarkedSoldBySeller()throws Exception {block(201,0);assertEquals(409,sellerStatus(201,"ON_SALE",1));assertEquals(409,sellerStatus(201,"SOLD",1));assertEquals(200,sellerStatus(201,"OFF_SHELF",1));assertEquals(1,version(201));assertEquals("BLOCKED",state(201));}
    @Test void sellerMayEditBlockedProductWithoutRemovingRestriction()throws Exception {block(201,0);assertEquals(200,mvc.perform(put("/api/products/201").header("Authorization",seller).contentType("application/json").content("{\"title\":\"已整改教材\",\"description\":\"整改后描述\",\"priceInCents\":3500,\"version\":1}")).andReturn().getResponse().getStatus());assertEquals(2,version(201));assertEquals("BLOCKED",state(201));assertEquals(409,sellerStatus(201,"ON_SALE",2));assertEquals("整改前描述",get("/api/products/201/moderation",seller).path("events").get(0).path("snapshot").path("description").asString());}
    @Test void ownerCanReadReasonButOtherAccountsCannot()throws Exception {block(201,0);assertEquals("平台发现违规内容",get("/api/products/201/moderation",seller).path("item").path("moderation").path("reason").asString());assertEquals(404,getStatus("/api/products/201/moderation",other));assertEquals(404,getStatus("/api/products/201/moderation",admin));assertEquals(401,getStatus("/api/products/201/moderation",null));}
    @Test void sellerAppealPreservesBlockReasonAndStaysOffShelf()throws Exception {block(201,0);var data=success(appeal(201,seller,1,"已经完成整改，请复核",key()));assertEquals("APPEALED",state(201));assertEquals(2,version(201));assertEquals("平台发现违规内容",data.path("detail").path("item").path("moderation").path("reason").asString());assertEquals("已经完成整改，请复核",data.path("detail").path("item").path("moderation").path("appealReason").asString());assertEquals(409,sellerStatus(201,"ON_SALE",2));assertEquals("SELLER",data.path("detail").path("events").get(0).path("actorRole").asString());}
    @Test void nonOwnerCannotAppealOrUseInjectedUserId()throws Exception {block(201,0);assertEquals(404,appeal(201,other,1,"伪造卖家申请",key()).getStatus());assertEquals(404,appeal(204,seller,0,"无归属商品",key()).getStatus());assertEquals(1,events());}
    @Test void clearOrAlreadyAppealedProductRejectsNewAppeal()throws Exception {assertEquals(409,appeal(201,seller,0,"当前无平台限制",key()).getStatus());block(201,0);success(appeal(201,seller,1,"首次申请复核",key()));assertEquals(409,appeal(201,seller,2,"重复申请复核",key()).getStatus());assertEquals(2,events());}
    @Test void releaseAllowsSellerToPublishButNeverAutoPublishes()throws Exception {block(201,0);success(appeal(201,seller,1,"已整改申请复核",key()));var data=success(action(201,admin,payload("RELEASE",2,"整改通过解除限制",key())));assertEquals("CLEAR",state(201));assertEquals(3,version(201));assertEquals("OFF_SHELF",data.path("detail").path("item").path("product").path("status").asString());assertEquals(404,getStatus("/api/products/201",null));assertEquals(200,sellerStatus(201,"ON_SALE",3));assertEquals(4,version(201));assertEquals(200,getStatus("/api/products/201",null));}
    @Test void administratorMayReleaseWithoutAppealAndReblockLater()throws Exception {block(201,0);success(action(201,admin,payload("RELEASE",1,"主动核查后解除",key())));assertEquals(200,sellerStatus(201,"ON_SALE",2));block(201,3);assertEquals("BLOCKED",state(201));assertEquals(3,events());}
    @Test void alreadyBlockedAndAlreadyClearActionsAreConflicts()throws Exception {assertEquals(409,action(201,admin,payload("RELEASE",0,"无可解除限制",key())).getStatus());block(201,0);assertEquals(409,action(201,admin,payload("BLOCK",1,"重复下架处理",key())).getStatus());assertEquals(1,events());}
    @Test void offShelfAndLegacyProductsCanBeRestricted()throws Exception {block(202,0);block(204,0);assertEquals(2,events());assertEquals("BLOCKED",state(204));assertTrue(get("/api/admin/products/204/moderation",admin).path("item").path("product").path("seller").isNull());}
    @Test void soldProductCannotBeModerated()throws Exception {assertEquals(409,action(203,admin,payload("BLOCK",0,"已售出商品",key())).getStatus());assertEquals(0,events());assertEquals(0,version(203));}
    @Test void reservedOrderPreventsBlockAndPreservesOrder()throws Exception {assertEquals(201,createOrder());assertEquals(409,action(201,admin,payload("BLOCK",1,"有待付款订单",key())).getStatus());assertEquals(0,events());assertEquals("PENDING_PAYMENT",jdbc.queryForObject("SELECT status FROM market_orders",String.class));assertEquals("ON_SALE",jdbc.queryForObject("SELECT status FROM products WHERE id=201",String.class));}
    @Test void staleVersionRejectsBlockAppealAndRelease()throws Exception {assertEquals(409,action(201,admin,payload("BLOCK",99,"旧版本拒绝",key())).getStatus());block(201,0);assertEquals(409,appeal(201,seller,0,"旧版本复核",key()).getStatus());assertEquals(409,action(201,admin,payload("RELEASE",0,"旧版本解除",key())).getStatus());assertEquals(1,events());}
    @Test void malformedPayloadAndUnsupportedActionAreRejected()throws Exception {for(var body:List.of(payload("APPEAL",0,"不支持操作",key()),payload("BLOCK",0," ",key()),payload("BLOCK",0,"x".repeat(201),key()),payload("BLOCK",-1,"版本错误",key()),payload("BLOCK",0,"标识错误","bad")))assertEquals(400,action(201,admin,body).getStatus());assertEquals(400,mvc.perform(post("/api/admin/products/201/moderation/actions").header("Authorization",admin).contentType("application/json").content("{\"action\":\"BLOCK\",\"reason\":\"小数版本\",\"version\":0.5,\"requestId\":\""+key()+"\"}")).andReturn().getResponse().getStatus());assertEquals(0,events());}
    @Test void missingProductAndInvalidIdsAreRejected()throws Exception {assertEquals(404,getStatus("/api/admin/products/999/moderation",admin));assertEquals(400,getStatus("/api/admin/products/0/moderation",admin));assertEquals(404,action(999,admin,payload("BLOCK",0,"不存在商品",key())).getStatus());}
    @Test void sameRequestReplaysWithoutAnotherVersionOrAudit()throws Exception {var body=payload("BLOCK",0,"同一请求重试",key());assertFalse(success(action(201,admin,body)).path("replayed").asBoolean());assertTrue(success(action(201,admin,body)).path("replayed").asBoolean());assertEquals(1,events());assertEquals(1,version(201));}
    @Test void replayAfterLaterReleaseDoesNotReapplyBlock()throws Exception {var body=payload("BLOCK",0,"延迟重试处理",key());success(action(201,admin,body));success(action(201,admin,payload("RELEASE",1,"后续解除限制",key())));var replay=success(action(201,admin,body));assertTrue(replay.path("replayed").asBoolean());assertEquals("CLEAR",replay.path("detail").path("item").path("moderation").path("state").asString());assertEquals(2,version(201));assertEquals(2,events());}
    @Test void reusedRequestIdCannotChangeReasonActionVersionOrProduct()throws Exception {String request=key();success(action(201,admin,payload("BLOCK",0,"初始原因",request)));for(var body:List.of(payload("BLOCK",0,"不同原因",request),payload("RELEASE",0,"初始原因",request),payload("BLOCK",1,"初始原因",request)))assertEquals(409,action(201,admin,body).getStatus());assertEquals(409,action(202,admin,payload("BLOCK",0,"初始原因",request)).getStatus());assertEquals(1,events());assertEquals(0,version(202));}
    @Test void sellerAppealReplayIsIdempotent()throws Exception {block(201,0);String request=key();success(appeal(201,seller,1,"复核重试同一申请",request));assertTrue(success(appeal(201,seller,1,"复核重试同一申请",request)).path("replayed").asBoolean());assertEquals(2,events());assertEquals(2,version(201));}
    @Test void revokedAdministratorCannotEvenReplayOldAction()throws Exception {var body=payload("BLOCK",0,"撤权后重试",key());success(action(201,admin,body));jdbc.update("DELETE FROM user_role_grants WHERE user_id=101");assertEquals(403,action(201,admin,body).getStatus());assertEquals(1,events());}
    @Test void failedAuditInsertRollsBackProductVersionAndRestriction()throws Exception {jdbc.execute("CREATE TRIGGER moderation_audit_fail BEFORE INSERT ON product_moderation_events FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private forced audit failure'");try{assertEquals(500,action(201,admin,payload("BLOCK",0,"审计失败回滚",key())).getStatus());}finally{jdbc.execute("DROP TRIGGER moderation_audit_fail");}assertEquals(0,version(201));assertEquals("ON_SALE",jdbc.queryForObject("SELECT status FROM products WHERE id=201",String.class));assertEquals(0,events());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM product_moderation",Integer.class));verify(cache,never()).evictAfterCommit(anyLong(),anyLong());}
    @Test void failedCurrentStateInsertRollsBackAlreadyInsertedAudit()throws Exception {jdbc.execute("CREATE TRIGGER moderation_state_fail BEFORE INSERT ON product_moderation FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='private forced state failure'");try{assertEquals(500,action(201,admin,payload("BLOCK",0,"状态失败回滚",key())).getStatus());}finally{jdbc.execute("DROP TRIGGER moderation_state_fail");}assertEquals(0,version(201));assertEquals(0,events());verify(cache,never()).evictAfterCommit(anyLong(),anyLong());}
    @Test void versionLimitIsAConflictWithoutPartialWrites()throws Exception {jdbc.update("UPDATE products SET version=9007199254740991 WHERE id=201");assertEquals(409,action(201,admin,payload("BLOCK",9_007_199_254_740_991L,"版本上限检查",key())).getStatus());assertEquals(0,events());}
    @Test void concurrentIdenticalSubmissionCreatesOneEvent()throws Exception {var body=payload("BLOCK",0,"并发同一请求",key());var result=parallel(()->action(201,admin,body).getStatus(),()->action(201,admin,body).getStatus());assertEquals(List.of(200,200),result);assertEquals(1,events());assertEquals(1,version(201));}
    @Test void concurrentDifferentAdministratorsCannotOverwriteDecision()throws Exception {var result=parallel(()->action(201,admin,payload("BLOCK",0,"管理员甲处理",key())).getStatus(),()->action(201,secondAdmin,payload("BLOCK",0,"管理员乙处理",key())).getStatus());assertTrue(result.contains(200)&&result.contains(409));assertEquals(1,events());assertEquals(1,version(201));}
    @Test void concurrentRequestIdReuseAcrossProductsRollsBackLoser()throws Exception {String request=key();var result=parallel(()->action(201,admin,payload("BLOCK",0,"跨商品请求竞争",request)).getStatus(),()->action(202,admin,payload("BLOCK",0,"跨商品请求竞争",request)).getStatus());assertTrue(result.contains(200)&&result.contains(409));assertEquals(1,events());assertEquals(1,version(201)+version(202));}
    @Test void orderAndModerationSerializeOnSameProduct()throws Exception {var result=parallel(()->action(201,admin,payload("BLOCK",0,"与下单竞争",key())).getStatus(),this::createOrder);boolean blocked=result.get(0)==200;assertEquals(blocked?1:0,events(),blocked?"one moderation event expected":"no moderation event after order wins");assertEquals(blocked?0:1,jdbc.queryForObject("SELECT COUNT(*) FROM market_orders",Integer.class));assertTrue(blocked?result.get(1)!=201:result.get(1)==201);}
    @Test void blockedProductsAreHiddenFromPublicListsFeedAndStore()throws Exception {block(201,0);assertEquals(404,getStatus("/api/products/201",null));assertEquals(0,get("/api/products?keyword=审核教材",null).path("total").asInt());assertTrue(get("/api/products/feed?keyword=审核教材",null).path("records").isEmpty());assertFalse(get("/api/sellers/102/products",null).toString().contains("审核教材"));}
    @Test void staleCachedBodyCannotRestoreBlockedPublicVisibility()throws Exception {block(201,0);doReturn(true).when(cache).canRead();try{clearInvocations(cache);assertEquals(404,getStatus("/api/products/201",null));verify(cache,never()).read(anyLong(),anyLong());}finally{doCallRealMethod().when(cache).canRead();}}
    @Test void reviewFiltersMatchBlockedAppealedAndClear()throws Exception {block(201,0);assertEquals(1,get("/api/admin/products?moderationState=BLOCKED",admin).path("total").asInt());success(appeal(201,seller,1,"筛选申请复核",key()));assertEquals(1,get("/api/admin/products?moderationState=APPEALED",admin).path("total").asInt());assertEquals(3,get("/api/admin/products?moderationState=CLEAR",admin).path("total").asInt());}
    @Test void eventsReturnNewestTwentyAndKeepAllAuditRows()throws Exception {long version=0;for(int i=0;i<11;i++){block(201,version++);success(action(201,admin,payload("RELEASE",version++,"审核解除第"+i+"次",key())));}var data=get("/api/admin/products/201/moderation",admin);assertEquals(22,events());assertEquals(20,data.path("events").size());assertTrue(data.path("events").get(0).path("id").asLong()>data.path("events").get(19).path("id").asLong());}
    @Test void roleAndActorCannotBeForgedInBody()throws Exception {var body=new HashMap<String,Object>(payload("BLOCK",0,"伪造操作者字段",key()));body.put("actorId",103);body.put("actorRole","SELLER");success(action(201,admin,body));assertEquals(101,jdbc.queryForObject("SELECT actor_id FROM product_moderation_events",Long.class));assertEquals("ADMIN",jdbc.queryForObject("SELECT actor_role FROM product_moderation_events",String.class));}
    @Test void adminNoStoreAndForeignOriginRulesApplyToNewEndpoints()throws Exception {assertEquals(403,mvc.perform(getRequest("/api/admin/products",admin).header("Origin","https://foreign.example")).andReturn().getResponse().getStatus());success(mvc.perform(getRequest("/api/admin/products",admin)).andReturn().getResponse());assertEquals(200,mvc.perform(options("/api/admin/products/201/moderation/actions").header("Origin","http://localhost:5173").header("Access-Control-Request-Method","POST").header("Access-Control-Request-Headers","authorization,content-type")).andReturn().getResponse().getStatus());}
    @Test void databaseRejectsAnInvalidStateTransition(){assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("INSERT INTO product_moderation_events(product_id,actor_id,actor_role,action,request_id,reason,from_state,to_state,from_version,to_version,product_snapshot) VALUES(201,101,'ADMIN','RELEASE',?,'bad','CLEAR','CLEAR',0,1,'{}')",key()));assertEquals(0,events());}
    @Test void publicProductResponseShapeDoesNotGainPrivateModerationData()throws Exception {var data=get("/api/products/201",null);assertFalse(data.has("moderation"));assertFalse(data.toString().contains("reason"));assertEquals(0,events());}
}
